-- composition of rule kernels common_aggregate x grouping_sets (duckdb), template graft_exists
SELECT a1.c0 AS c0, a1.c0 AS c1 FROM (SELECT * FROM t3 WHERE EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, BOOL_AND (FALSE) AS c1, [NULL]::text[] AS c2 FROM rc AS a1 GROUP BY ROLLUP (a1.c0) UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, []::text[] AS c2)) AS kb) OR NOT EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, BOOL_AND (FALSE) AS c1, [NULL]::text[] AS c2 FROM rc AS a1 GROUP BY ROLLUP (a1.c0) UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, []::text[] AS c2)) AS kb)) AS a1 WHERE (2 > ALL (SELECT a1.c0 AS c0)) INTERSECT (SELECT 17 AS c0, 10 AS c1 UNION SELECT 22 AS c0, 1 AS c1);
